    """
    Merges two dictionaries. If a key exists in both, the second dictionary's value overwrites the first's.
    Returns a new dictionary with the combined key-value pairs.
    """
    resultingMergedDictionary = firstInputDictionary.copy()
    for currentKeyItem, currentValueItem in secondInputDictionary.items():
        resultingMergedDictionary[currentKeyItem] = currentValueItem
    return resultingMergedDictionary

def exampleFunctionCallOne():
    initialFirstDictionary = {'a': 1, 'b': 2}
    initialSecondDictionary = {'b': 3, 'c': 4}
    combinedOutputDictionary = mergeDictionaries(initialFirstDictionary, initialSecondDictionary)
    print(combinedOutputDictionary)

