def transpose_matrix(original_matrix):
    if not original_matrix:
        return []

    number_of_rows = len(original_matrix)
    number_of_columns = len(original_matrix[0])

    transposed_result_matrix = []

    for column_index_counter in range(number_of_columns):
        current_transposed_row = []
        for row_index_iterator in range(number_of_rows):
            cell_value = original_matrix[row_index_iterator][column_index_counter]
            current_transposed_row.append(cell_value)
        transposed_result_matrix.append(current_transposed_row)

    return transposed_result_matrix

