class Queue:
    def __init__(self):
        self.internal_item_list = []

    def enqueue(self, item_to_add):
        self.internal_item_list.append(item_to_add)

    def dequeue(self):
        if not self.internal_item_list:
            return None
        removed_first_item = self.internal_item_list.pop(0)
        return removed_first_item

    def get_current_size(self):
        return len(self.internal_item_list)

    def check_if_empty(self):
        return len(self.internal_item_list) == 0

    def peek_front_item(self):
        if self.check_if_empty():
            return None
        return self.internal_item_list[0]

    def clear_all_items(self):
        self.internal_item_list = []

