def roman_to_int(roman_numeral_string):
    roman_value_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    integer_total_value = 0
    previous_digit_value = 0
    string_length = len(roman_numeral_string)

    for current_index in range(string_length - 1, -1, -1):
        current_roman_char = roman_numeral_string[current_index]
        current_digit_value = roman_value_map[current_roman_char]

        if current_digit_value < previous_digit_value:
            integer_total_value -= current_digit_value
        else:
            integer_total_value += current_digit_value
        previous_digit_value = current_digit_value

    final_numeric_result = integer_total_value
    return final_numeric_result

