def is_perfect_number(input_integer_value):
    if input_integer_value <= 1:
        return False

    sum_of_proper_divisors = 1
    current_divisor_candidate = 2

    while current_divisor_candidate * current_divisor_candidate <= input_integer_value:
        if input_integer_value % current_divisor_candidate == 0:
            sum_of_proper_divisors += current_divisor_candidate
            if current_divisor_candidate * current_divisor_candidate != input_integer_value:
                sum_of_proper_divisors += input_integer_value // current_divisor_candidate
        current_divisor_candidate += 1

    final_sum_comparison = (sum_of_proper_divisors == input_integer_value)
    return final_sum_comparison

