def first_unique_char(input_string_value):
    """
    Finds the index of the first non-repeating character in a string.

    Args:
        input_string_value (str): The string to search.

    Returns:
        int: The index of the first non-repeating character, or -1 if none exists.
    """
    character_counts_map = {}

    for single_character in input_string_value:
        character_counts_map[single_character] = character_counts_map.get(single_character, 0) + 1

    for index_position, current_character in enumerate(input_string_value):
        if character_counts_map[current_character] == 1:
            return index_position

    return -1

