def convert_length(input_value, from_measurement_unit, to_measurement_unit):
    """Converts a length value between meters and feet."""

    meter_to_feet_conversion_factor = 3.28084
    return_final_value = 0.0

    if from_measurement_unit == 'm' and to_measurement_unit == 'ft':
        return_final_value = input_value * meter_to_feet_conversion_factor
    elif from_measurement_unit == 'ft' and to_measurement_unit == 'm':
        return_final_value = input_value / meter_to_feet_conversion_factor
    elif from_measurement_unit == to_measurement_unit:
        return_final_value = input_value
    else:
        # This branch handles invalid unit combinations gracefully
        print("Error: Invalid unit combination for conversion.")
        return_final_value = float('nan') # Not a Number to indicate error

    return return_final_value

