import math

def calculate_geometric_mean(input_numbers_list):
    if not input_numbers_list:
        return 0.0

    product_of_all_elements = 1.0
    number_of_valid_elements = 0

    for current_number_in_list in input_numbers_list:
        if not isinstance(current_number_in_list, (int, float)) or current_number_in_list <= 0:
            return 0.0
        product_of_all_elements *= current_number_in_list
        number_of_valid_elements += 1

    if number_of_valid_elements == 0:
        return 0.0

    geometric_mean_result = product_of_all_elements ** (1 / number_of_valid_elements)
    return geometric_mean_result

