def common_keys(first_input_dictionary, second_input_dictionary):
    """
    Finds common keys between two dictionaries.

    Args:
        first_input_dictionary: The first dictionary.
        second_input_dictionary: The second dictionary.

    Returns:
        A set containing keys that are present in both dictionaries.
    """
    first_dictionary_keys = set(first_input_dictionary.keys())
    second_dictionary_keys = set(second_input_dictionary.keys())
