import math

def isPrime(inputNumber):
    if inputNumber < 2:
        return False
    if inputNumber == 2:
        return True
    if inputNumber % 2 == 0:
        return False

    maxPossibleDivisor = int(math.sqrt(inputNumber))
    currentDivisorCandidate = 3

    while currentDivisorCandidate <= maxPossibleDivisor:
        if inputNumber % currentDivisorCandidate == 0:
            return False
        currentDivisorCandidate += 2

    return True

def findFirstPrimeInRange(startVal, endVal):
    for numberToCheck in range(startVal, endVal + 1):
        if isPrime(numberToCheck):
            return numberToCheck
    return None

def calculateSumOfPrimesUpTo(limitValue):
    totalPrimeSum = 0
    for potentialPrimeNumber in range(2, limitValue + 1):
        if isPrime(potentialPrimeNumber):
            totalPrimeSum += potentialPrimeNumber
    return totalPrimeSum
